  "Audio (optional) — upload a clip or paste a URL": { en: "Audio (optional) — upload a clip or paste a URL", ar: "صوت (اختياري) — ارفع مقطعًا أو الصق رابطًا", uk: "Аудіо (необов'язково) — завантажте запис або вставте URL", fr: "Audio (facultatif) — téléversez un extrait ou collez une URL", de: "Audio (optional) — Clip hochladen oder URL einfügen" },
