  "Poll / vote (no points)": { en: "Poll / vote (no points)", ar: "استطلاع / تصويت (بدون نقاط)", uk: "Опитування / голосування (без балів)", fr: "Sondage / vote (sans points)", de: "Umfrage / Abstimmung (keine Punkte)" },
