  "⭐ Rating 1–5 (survey)": { en: "⭐ Rating 1–5 (survey)", ar: "⭐ تقييم ١–٥ (استبيان)", uk: "⭐ Оцінка 1–5 (опитування)", fr: "⭐ Note 1–5 (enquête)", de: "⭐ Bewertung 1–5 (Umfrage)" },
