  "⬇️ Download template": { en: "⬇️ Download template", ar: "⬇️ تنزيل القالب", uk: "⬇️ Завантажити шаблон", fr: "⬇️ Télécharger le modèle", de: "⬇️ Vorlage herunterladen" },
  "✨ Generate questions with AI": { en: "✨ Generate questions with AI", ar: "✨ توليد أسئلة بالذكاء الاصطناعي", uk: "✨ Згенерувати запитання за допомогою ШІ", fr: "✨ Générer des questions avec l'IA", de: "✨ Fragen mit KI generieren" },
  "Describe a topic, or upload a document (PDF, Word, PowerPoint, text), and QuizUps will draft multiple-choice questions.": { en: "Describe a topic, or upload a document (PDF, Word, PowerPoint, text), and QuizUps will draft multiple-choice questions.", ar: "صِف موضوعًا، أو ارفع مستندًا (PDF، Word، PowerPoint، نص)، وسيصيغ QuizUps أسئلة اختيار من متعدد.", uk: "Опишіть тему або завантажте документ (PDF, Word, PowerPoint, текст) — і QuizUps складе запитання з варіантами відповідей.", fr: "Décrivez un sujet ou téléversez un document (PDF, Word, PowerPoint, texte), et QuizUps rédigera des questions à choix multiples.", de: "Beschreibe ein Thema oder lade ein Dokument hoch (PDF, Word, PowerPoint, Text), und QuizUps entwirft Multiple-Choice-Fragen." },
  "Topic": { en: "Topic", ar: "الموضوع", uk: "Тема", fr: "Sujet", de: "Thema" },
  "Or generate from a document": { en: "Or generate from a document", ar: "أو التوليد من مستند", uk: "Або згенерувати з документа", fr: "Ou générer à partir d'un document", de: "Oder aus einem Dokument generieren" },
  "Reading document…": { en: "Reading document…", ar: "جارٍ قراءة المستند…", uk: "Читаємо документ…", fr: "Lecture du document…", de: "Dokument wird gelesen…" },
  "PDF, Word, PowerPoint or text. Long files are trimmed to keep AI free.": { en: "PDF, Word, PowerPoint or text. Long files are trimmed to keep AI free.", ar: "PDF أو Word أو PowerPoint أو نص. تُقتطع الملفات الطويلة لإبقاء الذكاء الاصطناعي مجانيًا.", uk: "PDF, Word, PowerPoint або текст. Довгі файли скорочуються, щоб ШІ лишався безкоштовним.", fr: "PDF, Word, PowerPoint ou texte. Les fichiers longs sont raccourcis pour garder l'IA gratuite.", de: "PDF, Word, PowerPoint oder Text. Lange Dateien werden gekürzt, damit die KI kostenlos bleibt." },
  "Or generate from a website URL": { en: "Or generate from a website URL", ar: "أو التوليد من رابط موقع", uk: "Або згенерувати з посилання на сайт", fr: "Ou générer à partir de l'URL d'un site web", de: "Oder aus einer Website-URL generieren" },
  "How many": { en: "How many", ar: "كم العدد", uk: "Скільки", fr: "Combien", de: "Wie viele" },
