  "AI can make mistakes — review the questions before publishing.": { en: "AI can make mistakes — review the questions before publishing.", ar: "قد يخطئ الذكاء الاصطناعي — راجِع الأسئلة قبل النشر.", uk: "ШІ може помилятися — перевірте запитання перед публікацією.", fr: "L'IA peut se tromper — vérifiez les questions avant de publier.", de: "Die KI kann Fehler machen — überprüfe die Fragen vor dem Veröffentlichen." },
  "Enter your question...": { en: "Enter your question...", ar: "اكتب سؤالك...", uk: "Введіть своє запитання...", fr: "Saisissez votre question...", de: "Gib deine Frage ein..." },
