  "...or paste an audio URL (.mp3)": { en: "...or paste an audio URL (.mp3)", ar: "...أو الصق رابط صوت (mp3.)", uk: "...або вставте URL аудіо (.mp3)", fr: "...ou collez une URL audio (.mp3)", de: "...oder füge eine Audio-URL ein (.mp3)" },
